return $input.all()
  .filter(item => item.json.formMode !== "test")
  .map(item => {

    delete item.json.formMode;

    const date = new Date(item.json.submittedAt);

    item.json.submittedAt = date.toLocaleString("en-ZA", {
      timeZone: "Africa/Johannesburg",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }) + " SAST";

    return item;
  });

const payload = JSON.parse($json.body.payload);

return [
  {
    json: payload
  }
];

const value = $json.actions[0].value;

const [decision, email] = value.split('|');

return [
  {
    json: {
      decision,
      email
    }
  }
];

