parameters.jsCode:
function generateSignalId(submittedAt) {

  const date = new Date(submittedAt);

  const year = date.getFullYear();

  const month = String(date.getMonth() + 1).padStart(2, '0');

  const day = String(date.getDate()).padStart(2, '0');

  const hours = String(date.getHours()).padStart(2, '0');

  const minutes = String(date.getMinutes()).padStart(2, '0');

  const seconds = String(date.getSeconds()).padStart(2, '0');

  return `SIG-${year}${month}${day}-${hours}${minutes}${seconds}`;
}

return $input.all()
  .filter(item => item.json.formMode !== 'test')
  .map(item => {

    delete item.json.formMode;

    item.json.signalId = generateSignalId(item.json.submittedAt);

    item.json.status = 'Pending Review';

    return item;
  });

const original = $('Prepare signal record').first().json;

const ai = $json.output;

const submittedDate = new Date(original.submittedAt);

const formattedSubmittedAt = submittedDate.toLocaleString('en-ZA', {
  timeZone: 'Africa/Johannesburg',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
}) + ' SAST';

return [
  {
    json: {
      ...original,

      submittedAt: formattedSubmittedAt,

      priority_score: ai.priority_score,

      sentiment: ai.sentiment,

      summary: ai.summary,

      recommended_action: ai.recommended_action
    }
  }
];

